using System.Text.Json;

class Schueler
{
    public string Name { get; set; } = "";
    public string Klasse { get; set; } = "";
    public List<int> Noten { get; set; }
        = [];
}

var s = new Schueler
{
    Name = "Lena", Klasse = "3AHIF",
    Noten = [1, 2, 1]
};
string json =
    JsonSerializer.Serialize(s);
Console.WriteLine(json);
// {"Name":"Lena","Klasse":"3AHIF",
//  "Noten":[1,2,1]}

var opt = new JsonSerializerOptions
{
    WriteIndented = true,
    PropertyNamingPolicy =
        JsonNamingPolicy.CamelCase,
    PropertyNameCaseInsensitive = true
};
string j = JsonSerializer
    .Serialize(s, opt);
// {
//   "name": "Lena",
//   "klasse": "3AHIF", ...

class Konto
{
    [JsonPropertyName("inhaber")]
    public string Inhaber { get; set; }
        = "";
    [JsonIgnore]
    public string Passwort { get; set; }
        = "";
    public decimal Stand { get; set; }
}
// {"inhaber":"Ali","Stand":12.5}

record Punkt(int X, int Y);
// {"X":3,"Y":4}

static void Speichern<T>(string pfad,
                         T daten)
{
    string json =
        JsonSerializer.Serialize(daten);
    File.WriteAllText(pfad, json);
}
static T? Laden<T>(string pfad)
{
    string json = File.ReadAllText(pfad);
    return JsonSerializer
        .Deserialize<T>(json);
}

Speichern("punkte.json",
    new List<Punkt> { new(1, 2) });
var p = Laden<List<Punkt>>(
    "punkte.json");

